template:
@php
    // A tab needs its title — it is the tab — and something to show under it; a picture deleted
    // from the library resolves without an address and is left out, not printed broken.
    $shown = [];
    foreach (is_array($tabs) ? $tabs : [] as $item) {
        if (! is_array($item)) {
            continue;
        }
        $title = wx_text($item['title'] ?? null)->plain();
        $image = is_array($item['picture'] ?? null) && ! empty($item['picture']['url']) ? $item['picture'] : null;
        $body = is_string($item['text'] ?? null) ? trim($item['text']) : '';
        if ($title === '' || ($image === null && $body === '')) {
            continue;
        }
        $shown[] = ['title' => $title, 'picture' => $image, 'text' => $body];
    }
    $label = $heading ? wx_text($heading)->plain() : null;
    // A block saved before a field had a value looks as a new one does.
    $place = in_array($picture_side ?? null, ['top', 'start', 'end'], true) ? $picture_side : 'top';
    $centred = ($align ?? null) === 'center';
    $fade = ($transition ?? null) === 'fade';
    $rows = (bool) ($wrap ?? false);
    $bleed = (bool) ($media_bleed ?? false);
@endphp
@if ($shown)
<section @class(['b-tabs', 'b-tabs--'.$place, 'b-tabs--center' => $centred, 'b-tabs--wrap' => $rows, 'b-tabs--bleed site-bleed' => $bleed]) data-wx-block="tabs"@webxOverlap($overlap ?? false)>
    @webxOverlapEdge($overlap ?? false, $overlap_edge ?? null, $overlap_edge_narrow ?? null)
    {{-- What fades when the next section slides over this one; the edge above stays whole. --}}
    <div class="b-tabs__inner" data-webx-overlap-fade>
    @if ($eyebrow ?? null)
        <p class="b-tabs__eyebrow">{{ $eyebrow }}</p>
    @endif
    @if ($heading)
        <h2 class="b-tabs__heading">{{ $heading }}</h2>
    @endif
    <x-webx-tabs class="b-tabs__tabs" :label="$label" :transition="$fade ? 'fade' : null">
        @foreach ($shown as $item)
            {{-- Without JavaScript every panel stands under its title; the runtime makes the titles tabs. --}}
            <x-webx-tabs.panel :title="$item['title']" :level="$heading ? 3 : 2">
                <div @class(['b-tabs__body', 'b-tabs__body--picture' => $item['picture'] && $item['text'] !== ''])>
                    @if ($item['picture'])
                        <img class="b-tabs__picture" src="{{ $item['picture']['url'] }}" alt="{{ $item['picture']['alt'] ?? '' }}" @if ($item['picture']['width']) width="{{ $item['picture']['width'] }}" height="{{ $item['picture']['height'] }}" @endif @unless ($loop->first) loading="lazy" @endunless>
                    @endif
                    @if ($item['text'] !== '')
                        <div class="b-tabs__text">{!! $item['text'] !!}</div>
                    @endif
                </div>
            </x-webx-tabs.panel>
        @endforeach
    </x-webx-tabs>
    </div>
</section>
@endif

styles:
.b-tabs {
    container-type: inline-size;
}


/* The section's rhythm (THEMES §7.2): none of its own until a site sets one, and no weight. */
:where(.b-tabs) {
    padding-block: var(--site-section-space, 0);
}

/* Its edge picture stands over its top, placed from the section — in a theme that does not
   position such sections itself too. */
.b-tabs[data-webx-overlap] {
    position: relative;
}

/* In the theme's smaller size where it has one; the block has no words of a theme of its own. */
.b-tabs__eyebrow {
    margin: 0 0 var(--site-eyebrow-space, 0.5em);
    /* Unset, the parent's: font-family and line-height are inherited. */
    font-family: var(--site-eyebrow-font);
    font-size: var(--site-eyebrow-size, var(--site-font-size-6, 0.875em));
    font-weight: var(--site-eyebrow-weight, 600);
    line-height: var(--site-eyebrow-line-height);
    letter-spacing: var(--site-eyebrow-letter-spacing, 0.08em);
    text-transform: var(--site-eyebrow-case, uppercase);
}

.b-tabs__heading {
    margin: 0 0 var(--site-section-head-space, 1em);
}

/* The section's H2 type (THEMES §7.2): unset, the prose's own, and only where the prose applies
   (in the main column and under site-prose), so that nothing changes until a site sets it. */
.b-tabs__heading:where(.site-main *, .site-prose *) {
    font-family: var(--site-section-title-font, var(--site-font-heading));
    font-size: var(--site-section-title-size, var(--site-font-size-2));
    line-height: var(--site-section-title-line-height, 1.2);
    /* Unset, nothing: an inherited property falls back to the parent's. */
    text-transform: var(--site-section-title-case);
}

.b-tabs--center .b-tabs__eyebrow,
.b-tabs--center .b-tabs__heading {
    text-align: center;
}

/* Centred by the margins of the end tabs, not by justify-content: a row wider than the column
   then still scrolls from its first tab instead of cutting it off on the left. */
.b-tabs--center .webx-tabs__tab:first-child {
    margin-inline-start: auto;
}

.b-tabs--center .webx-tabs__tab:last-child {
    margin-inline-end: auto;
}

/* In rows (`wrap`) where the column is narrow: the tabs share each row instead of scrolling. A
   site's theme may set how many stand in a row, `--b-tabs-per-row`; unset, as many as fit. */
@container (max-width: 39.99em) {
    .b-tabs--wrap .webx-tabs__list {
        flex-wrap: wrap;
        overflow-x: visible;
    }

    .b-tabs--wrap .webx-tabs__tab {
        flex-grow: 1;
        /* Unset, the length is invalid and the basis stays auto. */
        flex-basis: calc((100% - (var(--b-tabs-per-row) - 1) * var(--webx-tabs-gap)) / var(--b-tabs-per-row));
        margin-inline: 0;
    }
}

.b-tabs__body {
    display: grid;
    gap: 1em;
    align-items: start;
}

.b-tabs__picture {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 0.25em;
}

.b-tabs__text {
    min-width: 0;
}

.b-tabs__text > :first-child {
    margin-top: 0;
}

.b-tabs__text > :last-child {
    margin-bottom: 0;
}

/* Picture to the edges (`media_bleed`): the section spans the page (`site-bleed`) and its inner part
   keeps to the column with padding — as wide as the column a section without the option has, so
   on a wide screen nothing moves. The inner part is the container then, so the queries above and
   below measure the column, not the page. Only a direct child of the main column bleeds; anywhere
   else the option changes nothing. */
:where(.site-main) > .b-tabs--bleed > .b-tabs__inner {
    container-type: inline-size;
    padding-inline: max(
        var(--site-section-gutter, var(--site-gutter)),
        (100% - var(--site-container-width)) / 2 + var(--site-section-gutter, var(--site-gutter))
    );
}

/* Where the column is narrow the picture runs over the gutters to the page's sides, square. A
   picture beside the text stands above it here, so this is every picture of the block. */
@container (max-width: 39.99em) {
    :where(.site-main) > .b-tabs--bleed .b-tabs__picture {
        width: calc(100% + 2 * var(--site-section-gutter, var(--site-gutter)));
        max-width: none;
        margin-inline: calc(-1 * var(--site-section-gutter, var(--site-gutter)));
        border-radius: 0;
    }
}

/* Beside the text where the column has room for both, above it where it has not: the width of
   the column the block stands in decides, not the window. */
@container (min-width: 40em) {
    .b-tabs--start .b-tabs__body--picture,
    .b-tabs--end .b-tabs__body--picture {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 2em;
    }

    .b-tabs--end .b-tabs__body--picture .b-tabs__picture {
        order: 1;
    }
}
